// Generates the Python the visitor can take away.
//
// This is real, runnable pandas/scikit-learn code assembled from the same plan
// the browser executed, so what they run locally matches what they were shown.

export function buildPython(plan, profile, fileName) {
  const lines = [
    '"""',
    `Analysis of ${fileName}`,
    "",
    "Generated by the Mini-Lab at https://glp500.github.io/mini-lab/.",
    "The analysis was chosen by a local language model; every number was",
    "computed, not generated. This script reproduces that computation.",
    "",
    `Task: ${plan.task}${plan.target ? ` — target column "${plan.target}"` : ""}`,
    '"""',
    "",
    "import pandas as pd",
    "import numpy as np",
    "import matplotlib.pyplot as plt",
  ];

  if (plan.task === "classification") {
    lines.push(
      "from sklearn.model_selection import train_test_split, cross_val_score",
      "from sklearn.ensemble import RandomForestClassifier",
      "from sklearn.metrics import classification_report",
      "from sklearn.preprocessing import OrdinalEncoder"
    );
  } else if (plan.task === "regression") {
    lines.push(
      "from sklearn.model_selection import train_test_split, cross_val_score",
      "from sklearn.ensemble import RandomForestRegressor",
      "from sklearn.metrics import mean_absolute_error, r2_score",
      "from sklearn.preprocessing import OrdinalEncoder"
    );
  }

  const reader = /\.(xlsx|xls)$/i.test(fileName) ? "read_excel" : "read_csv";
  lines.push(
    "",
    `df = pd.${reader}(${JSON.stringify(fileName)})`,
    "",
    "# --- Shape and completeness -------------------------------------------",
    "print(df.shape)",
    "print(df.dtypes)",
    "print(df.isna().mean().sort_values(ascending=False))",
    "print(df.describe(include='all').T)",
    ""
  );

  const numericCols = profile.columns
    .filter((c) => c.type === "number" || c.type === "integer")
    .map((c) => c.name);

  if (plan.task === "correlation" || plan.task === "summary") {
    if (numericCols.length >= 2) {
      lines.push(
        "# --- Correlation -------------------------------------------------------",
        `numeric = ${py(numericCols)}`,
        "corr = df[numeric].corr(method='pearson')",
        "print(corr)",
        ""
      );
    }
  }

  plan.charts.forEach((chart, i) => {
    lines.push(`# --- Chart ${i + 1}: ${chart.kind} ---------------------------------------`);
    if (chart.kind === "histogram") {
      lines.push(
        `df[${py(chart.x)}].plot(kind='hist', bins=20, edgecolor='black')`,
        `plt.xlabel(${py(chart.x)})`
      );
    } else if (chart.kind === "bar") {
      lines.push(
        `df[${py(chart.x)}].value_counts().head(12).plot(kind='bar')`,
        `plt.xlabel(${py(chart.x)})`
      );
    } else if (chart.kind === "scatter") {
      lines.push(`df.plot(kind='scatter', x=${py(chart.x)}, y=${py(chart.y)}, alpha=0.6)`);
    }
    lines.push("plt.tight_layout()", "plt.show()", "");
  });

  if (plan.task === "classification" || plan.task === "regression") {
    const isClf = plan.task === "classification";
    lines.push(
      "# --- Model ---------------------------------------------------------------",
      "# Non-numeric predictors are ordinal-encoded so a tree model can use them.",
      `features = ${py(plan.features)}`,
      `target = ${py(plan.target)}`,
      "",
      "data = df[features + [target]].dropna()",
      "X = data[features].copy()",
      "y = data[target]",
      "",
      "categorical = X.select_dtypes(exclude='number').columns",
      "if len(categorical):",
      "    X[categorical] = OrdinalEncoder(",
      "        handle_unknown='use_encoded_value', unknown_value=-1",
      "    ).fit_transform(X[categorical].astype(str))",
      "",
      "X_train, X_test, y_train, y_test = train_test_split(",
      `    X, y, test_size=0.25, random_state=0${isClf ? ", stratify=y" : ""}`,
      ")",
      "",
      isClf
        ? "model = RandomForestClassifier(n_estimators=300, random_state=0)"
        : "model = RandomForestRegressor(n_estimators=300, random_state=0)",
      "model.fit(X_train, y_train)",
      "pred = model.predict(X_test)",
      ""
    );

    if (isClf) {
      lines.push(
        "print(classification_report(y_test, pred))",
        "# Compare against always predicting the most common class.",
        "print('majority baseline:', y.value_counts(normalize=True).max())"
      );
    } else {
      lines.push(
        "print('MAE:', mean_absolute_error(y_test, pred))",
        "print('R2 :', r2_score(y_test, pred))",
        "# Compare against always predicting the mean.",
        "print('baseline MAE:', mean_absolute_error(y_test, np.full_like(y_test, y_train.mean(), dtype=float)))"
      );
    }

    lines.push(
      "",
      "print(cross_val_score(model, X, y, cv=5))",
      "",
      "importance = pd.Series(model.feature_importances_, index=features)",
      "print(importance.sort_values(ascending=False))"
    );
  }

  return lines.join("\n");
}

export function buildRequirements(plan) {
  const reqs = ["pandas>=2.0", "numpy>=1.24", "matplotlib>=3.7"];
  if (plan.task === "classification" || plan.task === "regression") {
    reqs.push("scikit-learn>=1.3");
  }
  if (plan.fileName && /\.(xlsx|xls)$/i.test(plan.fileName)) reqs.push("openpyxl>=3.1");
  return reqs.join("\n");
}

function py(value) {
  return JSON.stringify(value);
}
